import{_ as d,o as r,c as o,ae as a}from"./chunks/framework.RRduUuAx.js";const c=JSON.parse('{"title":"架构师-备考 综合知识-网络与安全-网络安全技术","description":"","frontmatter":{"title":"架构师-备考 综合知识-网络与安全-网络安全技术"},"headers":[],"relativePath":"综合知识/网络与安全/网络安全技术.md","filePath":"综合知识/网络与安全/网络安全技术.md"}'),e={name:"综合知识/网络与安全/网络安全技术.md"};function n(l,t,s,h,i,g){return r(),o("div",null,[...t[0]||(t[0]=[a('<h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[x] 防火墙技术（网络级/应用级）</li><li>[x] 入侵检测系统 IDS vs 入侵防御系统 IPS</li><li>[x] DDoS 攻击与防御</li><li>[x] ARP/DNS/IP 欺骗原理</li><li>[x] 端口扫描技术（全TCP/SYN/FIN/第三方）</li><li>[x] SYN Flooding/ICMP/SNMP 攻击</li><li>[x] 网络攻击分类（被动/主动）</li><li>[x] 蜜罐系统</li><li>[x] 网络安全协议（SSL/SSH/SET/Kerberos/PGP/S/MIME）</li><li>[x] 第三方认证服务（Kerberos vs PKI）</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="一、防火墙-★" tabindex="-1">一、防火墙 ★ <a class="header-anchor" href="#一、防火墙-★" aria-label="Permalink to &quot;一、防火墙 ★&quot;">​</a></h3><blockquote><p>防火墙在内部网络和外部网络之间增加安全防护。</p></blockquote><table tabindex="0"><thead><tr><th>对比</th><th>网络级防火墙</th><th>应用级防火墙</th></tr></thead><tbody><tr><td><strong>工作层次</strong></td><td>低</td><td>高</td></tr><tr><td><strong>效率</strong></td><td><strong>高</strong></td><td>低</td></tr><tr><td><strong>检测方式</strong></td><td>包过滤+状态监测，检验网络包外在属性</td><td>拆包检查内部数据</td></tr><tr><td><strong>安全性</strong></td><td>较低（无法识别伪装的数据包）</td><td><strong>高</strong></td></tr><tr><td><strong>透明性</strong></td><td>对应用和用户透明</td><td>非透明</td></tr></tbody></table><blockquote><p>特点：防火墙主要分隔<strong>来自外网</strong>的威胁，对<strong>来自内网的直接攻击无能为力</strong>。</p></blockquote><hr><h3 id="二、入侵检测与防御-★" tabindex="-1">二、入侵检测与防御 ★ <a class="header-anchor" href="#二、入侵检测与防御-★" aria-label="Permalink to &quot;二、入侵检测与防御 ★&quot;">​</a></h3><table tabindex="0"><thead><tr><th>对比</th><th>IDS（入侵检测系统）</th><th>IPS（入侵防御系统）</th></tr></thead><tbody><tr><td><strong>位置</strong></td><td>防火墙之后，第二道屏障</td><td>安全网络之前的链路上</td></tr><tr><td><strong>工作方式</strong></td><td><strong>监听设备</strong>，不跨接在任何链路上</td><td><strong>实时检测并直接阻断</strong></td></tr><tr><td><strong>时机</strong></td><td>入侵行为<strong>发生后</strong>检测分析</td><td>入侵行为<strong>进入前</strong>防御</td></tr><tr><td><strong>原理</strong></td><td>监控行为→分析引擎与知识库匹配→检测入侵</td><td>实时检测→直接阻断</td></tr></tbody></table><blockquote><p>IDS 部署位置：(1)尽可能靠近攻击源 (2)尽可能靠近受保护资源。IDS 是对防火墙技术的补充。</p></blockquote><hr><h3 id="三、抗攻击技术-★" tabindex="-1">三、抗攻击技术 ★ <a class="header-anchor" href="#三、抗攻击技术-★" aria-label="Permalink to &quot;三、抗攻击技术 ★&quot;">​</a></h3><h4 id="密钥生成三因素" tabindex="-1">密钥生成三因素 <a class="header-anchor" href="#密钥生成三因素" aria-label="Permalink to &quot;密钥生成三因素&quot;">​</a></h4><p>增大密钥空间、选择强钥（复杂的）、密钥的随机性（使用随机数）。</p><h4 id="拒绝服务攻击-dos-ddos" tabindex="-1">拒绝服务攻击（DoS/DDoS） <a class="header-anchor" href="#拒绝服务攻击-dos-ddos" aria-label="Permalink to &quot;拒绝服务攻击（DoS/DDoS）&quot;">​</a></h4><blockquote><p>DoS：内部用户长时间占用 CPU/内存；外部黑客占用网络连接。DDoS：控制多台计算机<strong>同时</strong>向目标发起攻击，克服了传统 DoS 受网络资源限制和隐蔽性两大缺点。</p></blockquote><p><strong>外部 DoS 攻击模式</strong>：消耗资源、破坏或更改配置信息、物理破坏、利用服务程序错误使服务失效。</p><p><strong>防御方式</strong>：</p><ol><li>加强对数据包的特征识别（特征字符串）</li><li>设置防火墙监视本地主机端口使用</li><li>对通信数据量进行统计（超出正常极限）</li><li>尽可能修正已发现的问题和系统漏洞</li></ol><h4 id="syn-flooding-★" tabindex="-1">SYN Flooding ★ <a class="header-anchor" href="#syn-flooding-★" aria-label="Permalink to &quot;SYN Flooding ★&quot;">​</a></h4><blockquote><p>利用 TCP 三次握手机制，完成前两次，第三次不进行，造成大量<strong>半连接</strong>占满队列，使系统挂起。</p></blockquote><h4 id="arp-欺骗" tabindex="-1">ARP 欺骗 <a class="header-anchor" href="#arp-欺骗" aria-label="Permalink to &quot;ARP 欺骗&quot;">​</a></h4><blockquote><p>主机收到 ARP 响应分组即刷新 IP↔MAC 映射（不管是否有过请求）。攻击者构造虚假 IP+MAC 映射发送给目标，使得数据被监听。</p></blockquote><p><strong>防范</strong>：固化 ARP 表（arp -s）、使用 ARP 服务器、双向绑定、ARP 防护软件。</p><h4 id="dns-欺骗" tabindex="-1">DNS 欺骗 <a class="header-anchor" href="#dns-欺骗" aria-label="Permalink to &quot;DNS 欺骗&quot;">​</a></h4><blockquote><p>冒充域名服务器，将查询 IP 改为攻击者 IP。</p></blockquote><p><strong>检测方法：</strong></p><ul><li>被动监听检测：一个请求对应两个以上不同应答</li><li>虚假报文探测：向非 DNS 服务器发请求，收到应答说明被攻击</li><li>交叉检查查询：反向查询 IP 对应的 DNS 名是否一致</li></ul><h4 id="ip-欺骗流程" tabindex="-1">IP 欺骗流程 <a class="header-anchor" href="#ip-欺骗流程" aria-label="Permalink to &quot;IP 欺骗流程&quot;">​</a></h4><ol><li>使被冒充主机网络瘫痪 → 2. 连接到目标机猜测 ISN 基值和规律 → 3. 伪装源地址发送 SYN → 4. 等待目标发 SYN+ACK → 5. 再次伪装发送 ACK（预测 ISN+1）→ 6. 连接建立</li></ol><h4 id="端口扫描" tabindex="-1">端口扫描 <a class="header-anchor" href="#端口扫描" aria-label="Permalink to &quot;端口扫描&quot;">​</a></h4><table tabindex="0"><thead><tr><th>方式</th><th>原理</th></tr></thead><tbody><tr><td><strong>全 TCP 连接</strong></td><td>标准三次握手，建立连接</td></tr><tr><td><strong>半打开式（SYN）</strong></td><td>发 SYN，回复 SYN+ACK=活动端口，RST=死端口；收到 SYN+ACK 后发送 RST 拒绝连接</td></tr><tr><td><strong>FIN 扫描</strong></td><td>发 FIN：关闭端口→返回 RST，活动端口→不返回任何回应（秘密扫描）</td></tr><tr><td><strong>第三方扫描</strong></td><td>利用被入侵的第三方主机（肉鸡）代替攻击者扫描</td></tr></tbody></table><hr><h3 id="四、网络攻击分类-★" tabindex="-1">四、网络攻击分类 ★ <a class="header-anchor" href="#四、网络攻击分类-★" aria-label="Permalink to &quot;四、网络攻击分类 ★&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>攻击名称</th><th>说明</th></tr></thead><tbody><tr><td><strong>被动攻击</strong></td><td>窃听（网络监听）</td><td>窃取信息资源和敏感信息</td></tr><tr><td></td><td>业务流分析</td><td>长期监听+统计分析，发现信息流向规律</td></tr><tr><td></td><td>非法登录</td><td>部分资料归为被动攻击</td></tr><tr><td><strong>主动攻击</strong></td><td>假冒身份</td><td>冒充合法用户或提升特权</td></tr><tr><td></td><td>抵赖</td><td>否认自己发布的消息/伪造对方来信</td></tr><tr><td></td><td>旁路控制</td><td>利用安全缺陷获得非授权权利</td></tr><tr><td></td><td>重放攻击</td><td>截获合法通信数据重新发送</td></tr><tr><td></td><td>拒绝服务（DoS）</td><td>阻止合法访问</td></tr></tbody></table><hr><h3 id="五、其他安全技术" tabindex="-1">五、其他安全技术 <a class="header-anchor" href="#五、其他安全技术" aria-label="Permalink to &quot;五、其他安全技术&quot;">​</a></h3><p><strong>蜜罐系统</strong>：伪造蜜罐网络引诱黑客攻击，不影响安全网络，借此了解攻击手段以升级安全系统。</p><p><strong>杀毒软件</strong>：检测和解决计算机病毒（区别于防火墙处理网络非法攻击）。</p><hr><h3 id="六、网络安全协议-★" tabindex="-1">六、网络安全协议 ★ <a class="header-anchor" href="#六、网络安全协议-★" aria-label="Permalink to &quot;六、网络安全协议 ★&quot;">​</a></h3><table tabindex="0"><thead><tr><th>协议</th><th>全称</th><th>用途</th><th>备注</th></tr></thead><tbody><tr><td><strong>SSL</strong></td><td>安全套接字协议</td><td>加强 Web 安全传输</td><td>与 HTTP 结合→<strong>HTTPS</strong>，端口 443</td></tr><tr><td><strong>SSH</strong></td><td>安全外壳协议</td><td>加强 Telnet/FTP 安全传输</td><td>加密远程管理，替代明文 Telnet</td></tr><tr><td><strong>SET</strong></td><td>安全电子交易协议</td><td><strong>B2C 电子商务</strong>支付安全</td><td>PKI 框架典型实现，保证机密性/真实性/完整性/不可否认</td></tr><tr><td><strong>Kerberos</strong></td><td>网络身份认证协议</td><td>开放网络身份认证</td><td>基于<strong>信任第三方</strong>，不依赖主机OS/IP</td></tr><tr><td><strong>PGP</strong></td><td>安全电子邮件加密</td><td>邮件加密+签名</td><td>RSA认证+IDEA加密+MD5验证</td></tr><tr><td><strong>S/MIME</strong></td><td>安全多用途互联网邮件扩展</td><td><strong>安全电子邮件</strong></td><td>MIME 的安全扩展</td></tr></tbody></table><blockquote><p>路由器管理应使用 <strong>SSH</strong> 而非 Telnet（Telnet 明文传输不保证保密性）。</p></blockquote><p><strong>第三方认证两种体制：</strong></p><table tabindex="0"><thead><tr><th>体制</th><th>密钥/证书服务器</th><th>中文名</th></tr></thead><tbody><tr><td><strong>Kerberos</strong></td><td>KDC（密钥分发中心）</td><td>凯伯罗斯（三头犬）</td></tr><tr><td><strong>PKI</strong></td><td>CA（证书认证机构）</td><td>公钥基础设施</td></tr></tbody></table><hr><h3 id="七、pgp-协议详解" tabindex="-1">七、PGP 协议详解 <a class="header-anchor" href="#七、pgp-协议详解" aria-label="Permalink to &quot;七、PGP 协议详解&quot;">​</a></h3><blockquote><p>发送方 A 有 3 个密钥：A的私钥、B的公钥、A生成的一次性对称密钥。接收方 B 有 2 个密钥：B的私钥、A的公钥。</p></blockquote>',49)])])}const u=d(e,[["render",n]]);export{c as __pageData,u as default};
